<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/classes/GreenPortalDatabase.php';
require_once dirname(__DIR__) . '/classes/UsuarioSessao.php';
require_once dirname(__DIR__) . '/classes/PermissaoTransacao.php';
require_once dirname(__DIR__) . '/classes/TransactionSecurity.php';
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
if (empty($_SESSION['autenticado']) || empty($_SESSION['tenant']['banco_dados'])) { http_response_code(401); exit('Sessão expirada.'); }
$env = GreenPortalDatabase::env(); $pdo = TransactionSecurity::connect('REQUISITOS_LEGAIS');
if (!UsuarioSessao::atualizar($pdo, $_SESSION)) { http_response_code(401); exit('Sessão expirada.'); }
if (!PermissaoTransacao::obter('REQUISITOS_LEGAIS')['pode_visualizar']) { http_response_code(403); exit('Sem permissão para consultar responsabilidades.'); }
$id = filter_input(INPUT_GET, 'CODSITUACAO', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]); if (!$id) { http_response_code(400); exit('Situação inválida.'); }
$json = static fn(array $value): string => json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES); $e = static fn(mixed $value): string => htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');
$rows = GreenPortalDatabase::call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,1000,0)', ['tabela' => 'vw_responsabilidade_requisitos', 'filtros' => $json(['CODSITUACAO' => $id])]); $situation = $rows[0] ?? [];
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Responsabilidades do requisito</title><link rel="stylesheet" href="../assets/vendor/bootstrap/css/bootstrap.min.css?v=2"><link rel="stylesheet" href="../assets/vendor/bootstrap-icons/bootstrap-icons.css?v=2"><link rel="stylesheet" href="../assets/css/app.css?v=1"><?php require_once dirname(__DIR__) . '/components/pagina_padrao.php'; greenPortalEstiloPagina(); ?></head><body class="p-3 bg-light"><main class="container-fluid"><div class="mb-3"><h4 class="mb-1"><i class="bi bi-people me-2"></i>Responsabilidades do requisito</h4><div class="text-muted small">Situação <?= $e($id) ?> — <?= $e($situation['DESCRICAO_SITUACAO'] ?? 'Sem descrição') ?></div></div><?php if (!$rows): ?><div class="alert alert-info">Não há responsabilidades cadastradas para esta situação.</div><?php else: ?><div class="table-responsive border rounded bg-white"><table class="table table-sm table-hover align-middle mb-0"><thead class="table-light"><tr><th>Finalidade</th><th>Responsável</th><th>Destino</th><th>Origem</th><th>Situação</th><th>Validade</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr data-testid="responsibility-consulta-row" data-situacao="<?= $e($row['SITUACAO']) ?>"><td><?= $e($row['TIPO_NOME'] ?: 'Responsável pelo requisito') ?></td><td><?= $e($row['RESPONSAVEL_EXIBICAO']) ?><?php if (!empty($row['USUARIOS_ATIVOS_GRUPO'])): ?><div class="small text-muted"><?= $e($row['USUARIOS_ATIVOS_GRUPO']) ?> usuário(s) ativo(s)</div><?php endif; ?></td><td><?= $e($row['TIPO_DESTINO'] === 'GRUPO' ? 'Grupo' : 'Usuário') ?></td><td><?= $e($row['ORIGEM']) ?></td><td><span class="badge <?= $row['SITUACAO'] === 'ATIVA' ? 'text-bg-success' : 'text-bg-secondary' ?>"><?= $e($row['SITUACAO']) ?></span></td><td><?= $e($row['VALIDO_DE']) ?><?= $row['VALIDO_ATE'] ? ' a ' . $e($row['VALIDO_ATE']) : ' em diante' ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></main></body></html>
